CREATE UNIQUE INDEX preview_policy_credential_binding ON preview_access_policies(project_id,gateway_id,configuration_hash);
CREATE UNIQUE INDEX preview_credential_target_binding ON previews(project_id,preview_id,run_id);
CREATE TABLE preview_tickets(ticket_id TEXT PRIMARY KEY,project_id TEXT NOT NULL,gateway_id TEXT NOT NULL,configuration_hash TEXT NOT NULL,subject_principal_id TEXT NOT NULL,token_sha256 TEXT NOT NULL UNIQUE,target_json TEXT NOT NULL CHECK(json_valid(target_json)),platform_origin TEXT NOT NULL,preview_origin TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('ISSUED','CONSUMED')),session_id TEXT REFERENCES preview_sessions(session_id),consumed_at TEXT,audience TEXT NOT NULL CHECK(audience='devmesh.preview.ticket.v1'),preview_id TEXT GENERATED ALWAYS AS(json_extract(target_json,'$.previewId')) STORED NOT NULL,run_id TEXT GENERATED ALWAYS AS(json_extract(target_json,'$.runId')) STORED NOT NULL,UNIQUE(ticket_id,project_id,gateway_id),FOREIGN KEY(project_id,gateway_id,configuration_hash) REFERENCES preview_access_policies(project_id,gateway_id,configuration_hash),FOREIGN KEY(project_id,preview_id,run_id) REFERENCES previews(project_id,preview_id,run_id),CHECK(json_extract(target_json,'$.projectId') IS project_id),CHECK(platform_origin<>preview_origin),CHECK((state='ISSUED' AND session_id IS NULL AND consumed_at IS NULL) OR (state='CONSUMED' AND session_id IS NOT NULL AND consumed_at IS NOT NULL))) STRICT;
CREATE TABLE preview_sessions(session_id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL UNIQUE REFERENCES preview_tickets(ticket_id),project_id TEXT NOT NULL,gateway_id TEXT NOT NULL,configuration_hash TEXT NOT NULL,subject_principal_id TEXT NOT NULL,token_sha256 TEXT NOT NULL UNIQUE,target_json TEXT NOT NULL CHECK(json_valid(target_json)),platform_origin TEXT NOT NULL,preview_origin TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('ACTIVE','REVOKED')),revoked_at TEXT,audience TEXT NOT NULL CHECK(audience='devmesh.preview.session.v1'),preview_id TEXT GENERATED ALWAYS AS(json_extract(target_json,'$.previewId')) STORED NOT NULL,run_id TEXT GENERATED ALWAYS AS(json_extract(target_json,'$.runId')) STORED NOT NULL,FOREIGN KEY(ticket_id,project_id,gateway_id) REFERENCES preview_tickets(ticket_id,project_id,gateway_id),FOREIGN KEY(project_id,gateway_id,configuration_hash) REFERENCES preview_access_policies(project_id,gateway_id,configuration_hash),FOREIGN KEY(project_id,preview_id,run_id) REFERENCES previews(project_id,preview_id,run_id),CHECK(json_extract(target_json,'$.projectId') IS project_id),CHECK((state='ACTIVE' AND revoked_at IS NULL) OR (state='REVOKED' AND revoked_at IS NOT NULL))) STRICT;
CREATE TABLE preview_credential_events(kind TEXT NOT NULL CHECK(kind IN ('ticket','session')),credential_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision IN (0,1)),snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)),created_at TEXT NOT NULL,ticket_id TEXT GENERATED ALWAYS AS(CASE WHEN kind='ticket' THEN credential_id END) STORED REFERENCES preview_tickets(ticket_id),session_id TEXT GENERATED ALWAYS AS(CASE WHEN kind='session' THEN credential_id END) STORED REFERENCES preview_sessions(session_id),PRIMARY KEY(kind,credential_id,revision)) STRICT;
CREATE INDEX preview_ticket_capacity ON preview_tickets(project_id,subject_principal_id,state,expires_at);
CREATE INDEX preview_session_capacity ON preview_sessions(project_id,subject_principal_id,state,expires_at);
CREATE TRIGGER immutable_preview_ticket BEFORE UPDATE ON preview_tickets WHEN OLD.state<>'ISSUED' OR NEW.state<>'CONSUMED' OR NEW.session_id IS NULL OR NEW.consumed_at IS NULL OR NEW.ticket_id IS NOT OLD.ticket_id OR NEW.project_id IS NOT OLD.project_id OR NEW.gateway_id IS NOT OLD.gateway_id OR NEW.configuration_hash IS NOT OLD.configuration_hash OR NEW.subject_principal_id IS NOT OLD.subject_principal_id OR NEW.token_sha256 IS NOT OLD.token_sha256 OR NEW.target_json IS NOT OLD.target_json OR NEW.platform_origin IS NOT OLD.platform_origin OR NEW.preview_origin IS NOT OLD.preview_origin OR NEW.created_at IS NOT OLD.created_at OR NEW.expires_at IS NOT OLD.expires_at OR NEW.audience IS NOT OLD.audience BEGIN SELECT RAISE(ABORT,'PREVIEW_TICKET_IMMUTABLE'); END;
CREATE TRIGGER retained_preview_ticket BEFORE DELETE ON preview_tickets BEGIN SELECT RAISE(ABORT,'PREVIEW_TICKET_RETAINED'); END;
CREATE TRIGGER immutable_preview_session BEFORE UPDATE ON preview_sessions WHEN OLD.state<>'ACTIVE' OR NEW.state<>'REVOKED' OR NEW.revoked_at IS NULL OR NEW.session_id IS NOT OLD.session_id OR NEW.ticket_id IS NOT OLD.ticket_id OR NEW.project_id IS NOT OLD.project_id OR NEW.gateway_id IS NOT OLD.gateway_id OR NEW.configuration_hash IS NOT OLD.configuration_hash OR NEW.subject_principal_id IS NOT OLD.subject_principal_id OR NEW.token_sha256 IS NOT OLD.token_sha256 OR NEW.target_json IS NOT OLD.target_json OR NEW.platform_origin IS NOT OLD.platform_origin OR NEW.preview_origin IS NOT OLD.preview_origin OR NEW.created_at IS NOT OLD.created_at OR NEW.expires_at IS NOT OLD.expires_at OR NEW.audience IS NOT OLD.audience BEGIN SELECT RAISE(ABORT,'PREVIEW_SESSION_IMMUTABLE'); END;
CREATE TRIGGER retained_preview_session BEFORE DELETE ON preview_sessions BEGIN SELECT RAISE(ABORT,'PREVIEW_SESSION_RETAINED'); END;
CREATE TRIGGER immutable_preview_credential_event BEFORE UPDATE ON preview_credential_events BEGIN SELECT RAISE(ABORT,'PREVIEW_CREDENTIAL_EVENT_IMMUTABLE'); END;
CREATE TRIGGER retained_preview_credential_event BEFORE DELETE ON preview_credential_events BEGIN SELECT RAISE(ABORT,'PREVIEW_CREDENTIAL_EVENT_RETAINED'); END;
